#!/usr/bin/env python3
"""
benchmark.py

A stdlib-only benchmark harness for measuring TTFT (Time-To-First-Token)
across multiple LLM models using SSE streaming.

Usage:
    python benchmark.py --config models.json [--output results.json] [--timeout 10] [--workers 4]
"""

from __future__ import annotations

import argparse
import concurrent.futures
import datetime as dt
import json
import os
import socket
import sys
import time
import urllib.error
import urllib.request
import uuid
from typing import Any, Dict, Iterator, List, Optional

PROMPT = "Reply with exactly one sentence about the color blue."
DEFAULT_OUTPUT = "benchmark_results.json"


def iso_timestamp() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat()


def elapsed_ms(start: float, end: Optional[float] = None) -> float:
    if end is None:
        end = time.perf_counter()
    return round((end - start) * 1000.0, 1)


def load_config(path: str) -> List[Dict[str, Any]]:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if not isinstance(data, dict):
        raise ValueError("Config root must be a JSON object.")

    models = data.get("models")
    if not isinstance(models, list):
        raise ValueError("Config must contain a 'models' array.")

    return models


def require_nonempty_str(obj: Dict[str, Any], key: str) -> str:
    value = obj.get(key)
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"Model config missing or invalid '{key}'.")
    return value.strip()


def normalize_api_type(value: str) -> str:
    api_type = value.strip().lower()
    if api_type not in ("chat_completions", "responses"):
        raise ValueError(
            f"Unsupported api_type '{value}'. Expected 'chat_completions' or 'responses'."
        )
    return api_type


def endpoint_for_api_type(api_type: str) -> str:
    if api_type == "chat_completions":
        return "/v1/chat/completions"
    if api_type == "responses":
        return "/v1/responses"
    raise ValueError(f"Unsupported api_type '{api_type}'.")


def build_url(base_url: str, api_type: str) -> str:
    return base_url.rstrip("/") + endpoint_for_api_type(api_type)


def build_request_body(model_cfg: Dict[str, Any], prompt: str, api_type: str) -> Dict[str, Any]:
    body: Dict[str, Any] = {
        "model": model_cfg["id"],
        "stream": True,
    }

    if api_type == "chat_completions":
        body["messages"] = [{"role": "user", "content": prompt}]
    elif api_type == "responses":
        body["input"] = prompt
    else:
        raise ValueError(f"Unsupported api_type '{api_type}'.")

    for key in ("temperature", "max_tokens"):
        if key in model_cfg and model_cfg[key] is not None:
            body[key] = model_cfg[key]

    return body


def build_headers(api_key: str) -> Dict[str, str]:
    headers = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
        "User-Agent": "benchmark-harness/1.0",
    }

    # Send both for broader compatibility with different gateways/providers.
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
        headers["X-API-Key"] = api_key

    return headers


def decode_bytes(raw: bytes, charset: Optional[str]) -> str:
    used_charset = charset or "utf-8"
    try:
        return raw.decode(used_charset, errors="replace")
    except LookupError:
        return raw.decode("utf-8", errors="replace")


def iter_sse_data_events(response: Any) -> Iterator[str]:
    charset = response.headers.get_content_charset() or "utf-8"
    data_lines: List[str] = []

    while True:
        raw_line = response.readline()
        if not raw_line:
            if data_lines:
                yield "\n".join(data_lines)
            break

        try:
            line = raw_line.decode(charset, errors="replace").rstrip("\r\n")
        except LookupError:
            line = raw_line.decode("utf-8", errors="replace").rstrip("\r\n")

        if line == "":
            if data_lines:
                yield "\n".join(data_lines)
                data_lines = []
            continue

        if line.startswith("data:"):
            value = line[5:]
            if value.startswith(" "):
                value = value[1:]
            data_lines.append(value)


def extract_text_from_content_value(value: Any) -> Optional[str]:
    if isinstance(value, str):
        return value

    if isinstance(value, list):
        parts: List[str] = []
        for item in value:
            if isinstance(item, str):
                parts.append(item)
            elif isinstance(item, dict):
                text = item.get("text")
                if isinstance(text, str):
                    parts.append(text)
        if parts:
            return "".join(parts)

    return None


def extract_chat_completions_delta(event: Dict[str, Any]) -> Optional[str]:
    choices = event.get("choices")
    if not isinstance(choices, list) or not choices:
        return None

    first_choice = choices[0]
    if not isinstance(first_choice, dict):
        return None

    delta = first_choice.get("delta")
    if not isinstance(delta, dict):
        return None

    return extract_text_from_content_value(delta.get("content"))


def extract_responses_delta(event: Dict[str, Any]) -> Optional[str]:
    if event.get("type") != "content_block_delta":
        return None

    delta = event.get("delta")
    if not isinstance(delta, dict):
        return None

    text = delta.get("text")
    if isinstance(text, str):
        return text

    return None


def format_event_error(err: Any) -> str:
    if isinstance(err, str):
        return err
    if isinstance(err, dict):
        message = err.get("message")
        if isinstance(message, str) and message.strip():
            return message.strip()
        err_type = err.get("type")
        if isinstance(err_type, str) and err_type.strip():
            return err_type.strip()
        try:
            return json.dumps(err, ensure_ascii=False)
        except Exception:
            return str(err)
    return str(err)


def extract_stream_error(event: Any) -> Optional[str]:
    if not isinstance(event, dict):
        return None

    if event.get("type") == "error":
        return format_event_error(event.get("error", event))

    if "error" in event and event["error"]:
        return format_event_error(event["error"])

    return None


def format_http_error(exc: urllib.error.HTTPError) -> str:
    base = f"HTTP {exc.code}: {exc.reason}"

    try:
        raw = exc.read()
    except Exception:
        raw = b""

    if not raw:
        return base

    charset = None
    try:
        if exc.headers is not None:
            charset = exc.headers.get_content_charset()
    except Exception:
        charset = None

    body = decode_bytes(raw[:1000], charset).strip()
    if not body:
        return base

    return f"{base} - {body}"


def timeout_error_message(timeout_seconds: float) -> str:
    return f"Connection timeout after {int(timeout_seconds * 1000)}ms"


def benchmark_model(model_cfg: Any, prompt: str, timeout: float) -> Dict[str, Any]:
    result: Dict[str, Any] = {
        "model_id": None,
        "api_type": None,
        "status": "error",
        "ttft_ms": None,
        "total_ms": None,
        "first_token": None,
        "full_response": None,
        "error": None,
    }

    func_start = time.perf_counter()
    request_start: Optional[float] = None
    ttft_ms: Optional[float] = None
    first_token: Optional[str] = None
    chunks: List[str] = []

    try:
        if not isinstance(model_cfg, dict):
            raise ValueError("Model entry must be a JSON object.")

        model_id = require_nonempty_str(model_cfg, "id")
        api_type = normalize_api_type(require_nonempty_str(model_cfg, "api_type"))
        base_url = require_nonempty_str(model_cfg, "base_url")
        api_key_env = require_nonempty_str(model_cfg, "api_key_env")

        result["model_id"] = model_id
        result["api_type"] = api_type

        api_key = os.environ.get(api_key_env)
        if not api_key:
            raise RuntimeError(f"Missing API key in environment variable '{api_key_env}'.")

        url = build_url(base_url, api_type)
        body = build_request_body(model_cfg, prompt, api_type)
        payload = json.dumps(body).encode("utf-8")
        headers = build_headers(api_key)

        request = urllib.request.Request(
            url=url,
            data=payload,
            headers=headers,
            method="POST",
        )

        request_start = time.perf_counter()

        with urllib.request.urlopen(request, timeout=timeout) as response:
            for data_event in iter_sse_data_events(response):
                if not data_event:
                    continue

                if data_event.strip() == "[DONE]":
                    break

                try:
                    event = json.loads(data_event)
                except json.JSONDecodeError as e:
                    raise ValueError(
                        f"SSE JSON parse error: {e.msg} at line {e.lineno} column {e.colno}"
                    ) from e

                stream_error = extract_stream_error(event)
                if stream_error:
                    raise RuntimeError(stream_error)

                if api_type == "chat_completions":
                    text = extract_chat_completions_delta(event)
                else:
                    text = extract_responses_delta(event)

                if text is None:
                    continue

                if first_token is None and text != "":
                    ttft_ms = elapsed_ms(request_start)
                    stripped = text.strip()
                    first_token = stripped if stripped else text

                if text != "":
                    chunks.append(text)

        result["status"] = "ok"
        result["ttft_ms"] = ttft_ms
        result["first_token"] = first_token
        result["full_response"] = "".join(chunks)
        result["error"] = None

    except urllib.error.HTTPError as e:
        result["error"] = format_http_error(e)

    except (socket.timeout, TimeoutError):
        result["error"] = timeout_error_message(timeout)

    except urllib.error.URLError as e:
        reason_text = str(getattr(e, "reason", e))
        if isinstance(getattr(e, "reason", None), socket.timeout) or "timed out" in reason_text.lower():
            result["error"] = timeout_error_message(timeout)
        else:
            result["error"] = f"Connection error: {reason_text}"

    except Exception as e:
        result["error"] = str(e)

    finally:
        start_ref = request_start if request_start is not None else func_start
        result["total_ms"] = elapsed_ms(start_ref)

        # Preserve partial measurements if an error happened after streaming began.
        if result["status"] != "ok":
            if ttft_ms is not None:
                result["ttft_ms"] = ttft_ms
            if first_token is not None:
                result["first_token"] = first_token
            if chunks:
                result["full_response"] = "".join(chunks)

    return result


def build_worker_failure_result(model_cfg: Any, exc: Exception) -> Dict[str, Any]:
    model_id = None
    api_type = None

    if isinstance(model_cfg, dict):
        model_id = model_cfg.get("id")
        api_type = model_cfg.get("api_type")

    return {
        "model_id": model_id,
        "api_type": api_type,
        "status": "error",
        "ttft_ms": None,
        "total_ms": None,
        "first_token": None,
        "full_response": None,
        "error": f"Worker failure: {exc}",
    }


def run_benchmark(models: List[Dict[str, Any]], prompt: str, timeout: float, workers: int) -> List[Dict[str, Any]]:
    results: List[Optional[Dict[str, Any]]] = [None] * len(models)

    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
        future_to_index = {
            executor.submit(benchmark_model, model_cfg, prompt, timeout): idx
            for idx, model_cfg in enumerate(models)
        }

        for future in concurrent.futures.as_completed(future_to_index):
            idx = future_to_index[future]
            model_cfg = models[idx]
            try:
                results[idx] = future.result()
            except Exception as e:
                results[idx] = build_worker_failure_result(model_cfg, e)

    return [r for r in results if r is not None]


def build_summary(results: List[Dict[str, Any]]) -> Dict[str, Any]:
    total = len(results)
    ok_results = [r for r in results if r.get("status") == "ok"]
    error_count = total - len(ok_results)

    ttft_results = [
        r for r in ok_results
        if isinstance(r.get("ttft_ms"), (int, float))
    ]

    if ttft_results:
        avg_ttft = round(
            sum(float(r["ttft_ms"]) for r in ttft_results) / len(ttft_results),
            1,
        )
        fastest_model = min(ttft_results, key=lambda r: float(r["ttft_ms"]))["model_id"]
        slowest_model = max(ttft_results, key=lambda r: float(r["ttft_ms"]))["model_id"]
    else:
        avg_ttft = None
        fastest_model = None
        slowest_model = None

    return {
        "total": total,
        "ok": len(ok_results),
        "errors": error_count,
        "avg_ttft_ms": avg_ttft,
        "fastest_model": fastest_model,
        "slowest_model": slowest_model,
    }


def write_json(path: str, data: Dict[str, Any]) -> None:
    directory = os.path.dirname(os.path.abspath(path))
    os.makedirs(directory, exist_ok=True)

    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")


def parse_args(argv: Optional[List[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Benchmark multiple LLM models and measure streaming TTFT via SSE."
    )
    parser.add_argument("--config", required=True, help="Path to model config JSON.")
    parser.add_argument(
        "--output",
        default=DEFAULT_OUTPUT,
        help=f"Output file path (default: {DEFAULT_OUTPUT})",
    )
    parser.add_argument(
        "--timeout",
        type=float,
        default=30.0,
        help="Per-model timeout in seconds (default: 30)",
    )
    parser.add_argument(
        "--workers",
        type=int,
        default=1,
        help="Parallel worker threads (default: 1)",
    )

    args = parser.parse_args(argv)

    if args.timeout <= 0:
        parser.error("--timeout must be greater than 0.")

    if args.workers <= 0:
        parser.error("--workers must be greater than 0.")

    return args


def main(argv: Optional[List[str]] = None) -> int:
    args = parse_args(argv)

    try:
        models = load_config(args.config)
    except FileNotFoundError:
        print(f"Config file not found: {args.config}", file=sys.stderr)
        return 1
    except json.JSONDecodeError as e:
        print(f"Failed to parse config JSON: {e}", file=sys.stderr)
        return 1
    except Exception as e:
        print(f"Failed to load config: {e}", file=sys.stderr)
        return 1

    run_id = str(uuid.uuid4())
    timestamp = iso_timestamp()

    results = run_benchmark(
        models=models,
        prompt=PROMPT,
        timeout=args.timeout,
        workers=args.workers,
    )

    output_data = {
        "run_id": run_id,
        "timestamp": timestamp,
        "prompt": PROMPT,
        "results": results,
        "summary": build_summary(results),
    }

    try:
        write_json(args.output, output_data)
    except Exception as e:
        print(f"Failed to write output file: {e}", file=sys.stderr)
        return 1

    summary = output_data["summary"]
    print(f"Wrote results to {args.output}")
    print(
        f"total={summary['total']} ok={summary['ok']} "
        f"errors={summary['errors']} avg_ttft_ms={summary['avg_ttft_ms']}"
    )

    return 0


if __name__ == "__main__":
    sys.exit(main())
